ee:message.ee:set-payload:
%dw 2.0
import toProcessRegistration from dwl::PortalView
output application/json
var request = readUrl("classpath://samples/portal-case1-ana.json", "application/json")
---
{
    plain:    toProcessRegistration(request),
    override: toProcessRegistration(request ++ { channel: "KIOSK" })
}

%dw 2.0
import fingerprint from dwl::Idempotency
output application/json
var request = readUrl("classpath://samples/portal-case1-ana.json", "application/json")
var reordered = {
    consents: { smsReminders: false, dataProcessing: true },
    contact: { phone: "+387 61 111-222", email: "Ana.Kovac@Example.com" },
    gender: "female", dateOfBirth: "1985-04-12", lastName: "KOVAČ", firstName: "  ana "
}
---
{
    same: fingerprint(request) == fingerprint(reordered),
    changed: fingerprint(request) == fingerprint(request update { case .firstName -> "Ana" }),
    format: fingerprint(request) matches /^[0-9a-f]{64}$/
}
